#include "doveos.h"
#include <stdio.h>
#include "dove_gpu_canvas.h"
static DoveGpuCanvas *canvas;
static GtkWidget *position,*last,*counts,*logview;
static unsigned left,right,middle,moves,scrolls;static double px,py;static gboolean moved;
static void log_event(const char*s){GtkTextBuffer*b=gtk_text_view_get_buffer(GTK_TEXT_VIEW(logview));GtkTextIter e;gtk_text_buffer_get_end_iter(b,&e);gtk_text_buffer_insert(b,&e,s,-1);gtk_text_buffer_insert(b,&e,"\n",1);if(gtk_text_buffer_get_line_count(b)>24){GtkTextIter a,z;gtk_text_buffer_get_start_iter(b,&a);gtk_text_buffer_get_iter_at_line(b,&z,1);gtk_text_buffer_delete(b,&a,&z);}gtk_text_buffer_get_end_iter(b,&e);gtk_text_view_scroll_to_iter(GTK_TEXT_VIEW(logview),&e,0,FALSE,0,0);}
static gboolean tick(gpointer unused){(void)unused;char s[200];if(moved){snprintf(s,sizeof s,"Pointer: X %.0f, Y %.0f  |  Movement events: %u",px,py,moves);gtk_label_set_text(GTK_LABEL(position),s);moved=FALSE;}snprintf(s,sizeof s,"Left: %u    Right: %u    Middle: %u    Scroll: %u",left,right,middle,scrolls);gtk_label_set_text(GTK_LABEL(counts),s);return TRUE;}
static gboolean motion(GtkWidget*w,GdkEventMotion*e,gpointer u){(void)w;(void)u;px=e->x;py=e->y;moves++;moved=TRUE;dove_gpu_canvas_pointer(canvas,e->x,e->y,e->state&(GDK_BUTTON1_MASK|GDK_BUTTON2_MASK|GDK_BUTTON3_MASK));return TRUE;}
static gboolean click(GtkWidget*w,GdkEventButton*e,gpointer u){(void)w;(void)u;dove_gpu_canvas_pointer(canvas,e->x,e->y,e->type==GDK_BUTTON_RELEASE?0:e->button);char s[160];const char*name=e->button==1?"Button 1 - LEFT":e->button==3?"Button 2 - RIGHT":e->button==2?"MIDDLE":"Extra button";const char*action=e->type==GDK_BUTTON_RELEASE?"released":e->type==GDK_2BUTTON_PRESS?"double click":e->type==GDK_3BUTTON_PRESS?"triple click":"pressed";if(e->type==GDK_BUTTON_PRESS){if(e->button==1)left++;else if(e->button==3)right++;else if(e->button==2)middle++;}snprintf(s,sizeof s,"%s %s  (Linux button %u)",name,action,e->button);gtk_label_set_text(GTK_LABEL(last),s);log_event(s);return TRUE;}
static gboolean scroll(GtkWidget*w,GdkEventScroll*e,gpointer u){(void)w;(void)u;const char*name=e->direction==GDK_SCROLL_UP?"UP":e->direction==GDK_SCROLL_DOWN?"DOWN":e->direction==GDK_SCROLL_LEFT?"LEFT":"RIGHT";char s[64];scrolls++;snprintf(s,sizeof s,"Scroll %s",name);gtk_label_set_text(GTK_LABEL(last),s);log_event(s);return TRUE;}
static void reset(GtkWidget*w,gpointer u){(void)w;(void)u;left=right=middle=moves=scrolls=0;dove_gpu_canvas_pointer(canvas,0,0,0);gtk_text_buffer_set_text(gtk_text_view_get_buffer(GTK_TEXT_VIEW(logview)),"",-1);gtk_label_set_text(GTK_LABEL(last),"Waiting for a click...");gtk_label_set_text(GTK_LABEL(position),"Move the pointer inside the test area.");tick(NULL);}
int main(int argc,char**argv){gtk_init(&argc,&argv);GtkWidget*window=dove_window("Mouse Test",620,440);g_signal_connect(window,"destroy",G_CALLBACK(gtk_main_quit),NULL);GtkWidget*box=gtk_vbox_new(FALSE,6);gtk_container_set_border_width(GTK_CONTAINER(box),10);gtk_container_add(GTK_CONTAINER(window),box);dove_add(box,dove_label("Touchpad and mouse test - move, tap, press the physical buttons, or scroll inside the area below."));position=dove_label("Move the pointer inside the test area.");dove_add(box,position);last=dove_label("Waiting for a click...");dove_add(box,last);counts=dove_label("");dove_add(box,counts);canvas=dove_gpu_canvas_new();GtkWidget*area=canvas->area;gtk_widget_set_size_request(area,-1,130);dove_add(box,dove_label("GPU test area - move, click or scroll here."));gtk_widget_add_events(area,GDK_POINTER_MOTION_MASK|GDK_BUTTON_PRESS_MASK|GDK_BUTTON_RELEASE_MASK|GDK_SCROLL_MASK);gtk_box_pack_start(GTK_BOX(box),area,TRUE,TRUE,0);g_signal_connect(area,"motion-notify-event",G_CALLBACK(motion),NULL);g_signal_connect(area,"button-press-event",G_CALLBACK(click),NULL);g_signal_connect(area,"button-release-event",G_CALLBACK(click),NULL);g_signal_connect(area,"scroll-event",G_CALLBACK(scroll),NULL);GtkWidget*scroller=gtk_scrolled_window_new(NULL,NULL);gtk_widget_set_size_request(scroller,-1,105);gtk_scrolled_window_set_policy(GTK_SCROLLED_WINDOW(scroller),GTK_POLICY_AUTOMATIC,GTK_POLICY_AUTOMATIC);logview=gtk_text_view_new();gtk_text_view_set_editable(GTK_TEXT_VIEW(logview),FALSE);gtk_text_view_set_cursor_visible(GTK_TEXT_VIEW(logview),FALSE);gtk_container_add(GTK_CONTAINER(scroller),logview);dove_add(box,scroller);GtkWidget*button=gtk_button_new_with_label("Reset counters");dove_add(box,button);g_signal_connect(button,"clicked",G_CALLBACK(reset),NULL);tick(NULL);g_timeout_add(50,tick,NULL);gtk_widget_show_all(window);gtk_main();return 0;}
